import java.util.*;

class Solution {
  public String maximumOddBinaryNumber(String s) {
    int ones = 0;
    for (int i = 0; i < s.length(); i++) if (s.charAt(i) == '1') ones++;
    char[] result = new char[s.length()];
    Arrays.fill(result, '0');
    result[s.length() - 1] = '1';
    for (int i = 0; i < ones - 1; i++) result[i] = '1';
    return new String(result);
  }
}
